CREATE OR REPLACE VIEW dq.v_column_completeness AS SELECT table_name,column_name,COUNT(*) FILTER(WHERE value IS NULL OR btrim(value)='') AS null_count,COUNT(*) AS record_count FROM (SELECT 'DIM_CUSTOMER' table_name,'phone_number' column_name,phone_number value FROM landing.dim_customer UNION ALL SELECT 'FACT_POLICY','policy_id',policy_id FROM landing.fact_policy UNION ALL SELECT 'FACT_LEAD_FUNNEL','lead_id',lead_id FROM landing.fact_lead_funnel) x GROUP BY 1,2;
CREATE OR REPLACE VIEW dq.v_policy_integrity AS SELECT p.policy_id,p.customer_id,CASE WHEN c.customer_id IS NULL THEN 'MISSING_CUSTOMER' END AS exception FROM core.policy p LEFT JOIN core.customer c USING(customer_id) WHERE c.customer_id IS NULL;
CREATE OR REPLACE VIEW dq.v_profile_summary AS SELECT 'policy' entity,COUNT(*) records,COUNT(DISTINCT policy_id) distinct_keys,COUNT(*) FILTER(WHERE premium_amount IS NULL OR premium_amount < 0) invalid_premium FROM core.policy UNION ALL SELECT 'lead',COUNT(*),COUNT(DISTINCT lead_id),COUNT(*) FILTER(WHERE lead_status_date IS NULL) FROM core.lead;
